//! Distances between a variant and a feature.

/// The distance from a position to the nearest end of a feature.
pub fn flank_distance(start: u64, end: u64, position: u64) -> u64 {
    if position < start {
        start - position
    } else {
        position.saturating_sub(end)
    }
}

/// Whether a position lies inside a feature.
pub fn inside(start: u64, end: u64, position: u64) -> bool {
    start <= position && position <= end
}

